-- Singapore milestones (Stage 4 deep-dive/tracker migration)
-- 10 total: 6 deep-dive-only + 4 tracker-matched (sg-voluntary2025, sg-allvoluntary,
-- sg-existing2028, sg-full2031), all exact date matches with the tracker's DATA entries.
-- sg-existing2028 uses the tracker's own phrasing ("Phased rollout begins for existing
-- GST-registered businesses") rather than the deep-dive's narrower band-specific title
-- ("New GST taxpayers, annual sales <= S$200,000"), per tracker-phrasing-wins.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-first-peppol-2018', id, '2018-05-01', 0, NULL FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-first-peppol-2018', 'en', 'Singapore becomes first Peppol Authority outside Europe', 'A significant early milestone establishing Singapore''s role in the Peppol ecosystem well ahead of any GST mandate.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-invoicenow-launch-2019', id, '2019-01-01', 0, NULL FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-invoicenow-launch-2019', 'en', 'InvoiceNow launches', 'IMDA introduces Singapore''s national e-invoicing network, based on Peppol, for voluntary structured invoice exchange in both B2B and B2G.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-b2g-channel-2020', id, '2020-01-01', 0, NULL FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-b2g-channel-2020', 'en', 'InvoiceNow added as a B2G channel', 'Government procurement gains InvoiceNow as a preferred submission channel for suppliers.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-voluntary-phase-2025', id, '2025-05-01', 0, NULL FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary-phase-2025', 'en', 'Voluntary phase of GST InvoiceNow Requirement begins', 'Existing GST-registered businesses can voluntarily submit invoice data to IRAS through InvoiceNow, ahead of any mandatory obligation.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-voluntary2025', id, '2025-11-01', 1, 'https://www.iras.gov.sg/taxes/goods-services-tax-(gst)/gst-invoicenow-requirement' FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary2025', 'en', 'GST InvoiceNow mandatory — new voluntary GST registrants (within 6mo of incorporation)', 'The first mandatory phase of GST InvoiceNow required companies voluntarily registering for GST within six months of incorporation to transmit invoice data to IRAS via the Peppol-based InvoiceNow network.', '["New qualifying GST registrants: set up an InvoiceNow-Ready Solution and Peppol ID at the point of registration"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-allvoluntary', id, '2026-04-01', 0, 'https://www.iras.gov.sg/taxes/goods-services-tax-(gst)/gst-invoicenow-requirement' FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-allvoluntary', 'en', 'Mandate extends to all new voluntary GST registrants', 'All new voluntary GST registrants, regardless of incorporation date or business structure, must adopt InvoiceNow as a condition of GST registration.', '["Factor InvoiceNow setup into your GST registration application from this date", "Use IRAS''s implementation date calculator if unsure which phase applies to you"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-existing2028', id, '2028-04-01', 0, 'https://www.iras.gov.sg/taxes/goods-services-tax-(gst)/gst-invoicenow-requirement' FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-existing2028', 'en', 'Phased rollout begins for existing GST-registered businesses', 'Existing GST-registered businesses begin to be brought into GST InvoiceNow on a phased schedule running through to full adoption in 2031. IRAS is notifying affected businesses of their specific date during 2026.', '["Use IRAS''s GST InvoiceNow Implementation Date Calculator to determine your applicable date", "Watch for direct notification from IRAS (expected by mid-2026)"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-phase-2029', id, '2029-04-01', 0, NULL FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-phase-2029', 'en', 'Existing taxpayers, annual sales ≤ S$1 million', 'The phased extension continues with the next revenue band of existing GST-registered businesses brought into scope.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-phase-2030', id, '2030-04-01', 0, NULL FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-phase-2030', 'en', 'Existing taxpayers, annual sales ≤ S$4 million', 'The phased extension continues with the next revenue band of existing GST-registered businesses brought into scope.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sg-full2031', id, '2031-04-01', 0, 'https://www.iras.gov.sg/taxes/goods-services-tax-(gst)/gst-invoicenow-requirement' FROM countries WHERE name_en = 'Singapore';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-full2031', 'en', 'Full adoption — all GST-registered businesses', 'By this date, every GST-registered business in Singapore, including large multinational enterprises, must transmit invoice data via InvoiceNow.', '["Plan integration well in advance — transitional government grants are available to support adoption"]');
